-- PREPARED -- NOT APPLIED.
--
-- CA: fill missing Google Place IDs, phone numbers and websites
-- (world contact-gap export of 2026-11-04). Generated by
-- world_contact_gaps/scripts/build_contact_fill_sql.py from the reviewed
-- research in ca_contact_fill.csv (evidence and the reason per row,
-- including every value held back).
--
-- Fill-only: a value is written only where the field is NULL; nothing is
-- overwritten. Place ID: the venue's own Google record (restaurant, or lodging
-- for a hotel), within 100 m of the stored point, or 100-500 m with the
-- official domain; never a hotel's record for a named restaurant inside it;
-- no search in mainland China. Phone: MICHELIN and Google agreeing, or the
-- number printed on the venue's own site; for a restaurant in a hotel only its
-- own page. Website: MICHELIN's link and the Google record agreeing on the
-- domain, or a site that loads and names the venue in its title or address;
-- never a booking, aggregator or social link; tracking parameters removed.
--
-- One transaction; any failed check rolls the whole file back. Safe to
-- re-run (fill-only).

begin;
-- restaurants: 8 rows (8 Place IDs, 4 phones, 0 websites)
create temp table _fill_restaurant (code text primary key, name text not null, place_id text unique, phone text, website text) on commit drop;
insert into _fill_restaurant values
    ('rest_3235', 'DaNico', 'ChIJLxOGU8s1K4gRgdxAIsLtxB8', NULL, NULL),
    ('rest_3236', 'Don Alfonso 1890', 'ChIJzUm3X2TL1IkRDkPiZYlOC7U', NULL, NULL),
    ('rest_3244', 'Kebec Club Privé', 'ChIJ6yHKky-XuEwRevN9SNTIbNo', '+1 819 342 2030', NULL),
    ('rest_3251', 'Narval', 'ChIJCxbsKPrZlUwRwmTIY-mNbW8', NULL, NULL),
    ('rest_3256', 'Restaurant 20 Victoria', 'ChIJJYukdjfL1IkRmO6n1JfjfKU', '+1 416 804 6066', NULL),
    ('rest_3261', 'Sumibiyaki Arashi', 'ChIJHT2qdw9xhlQRgfZgfKBAeq0', NULL, NULL),
    ('rest_3264', 'Sushi Masuda', 'ChIJsX0QBDBxhlQRiAP9i2t_vv8', '+1 604 816 3312', NULL),
    ('rest_3267', 'The Pine', 'ChIJy4dyoG97KogRGYpXlpA4Ip4', '+1 705 466 2888', NULL);

do $$
declare bad text;
begin
  -- identity: each code must still be the CA row of that name
  select string_agg(f.code, ', ') into bad from _fill_restaurant f
   where not exists (select 1 from public.restaurants x where x.restaurant_code = f.code and x.name = f.name and x.country_code = 'CA');
  if bad is not null then raise exception 'restaurants: code is no longer the exported CA row: %', bad; end if;
  -- Place IDs are unique per table
  select string_agg(f.code || ' -> ' || f.place_id || ' (held by ' || x.restaurant_code || ')', '; ') into bad
    from _fill_restaurant f join public.restaurants x on x.google_place_id = f.place_id and x.restaurant_code <> f.code;
  if bad is not null then raise exception 'restaurants: Place ID already used by another row: %', bad; end if;
end $$;

update public.restaurants x set google_place_id = f.place_id, updated_at = now()
  from _fill_restaurant f where x.restaurant_code = f.code and f.place_id is not null and x.google_place_id is null;
update public.restaurants x set phone = f.phone, updated_at = now()
  from _fill_restaurant f where x.restaurant_code = f.code and f.phone is not null and x.phone is null;
update public.restaurants x set website_url = f.website, updated_at = now()
  from _fill_restaurant f where x.restaurant_code = f.code and f.website is not null and x.website_url is null;

-- hotels: 11 rows (11 Place IDs, 7 phones, 3 websites)
create temp table _fill_hotel (code text primary key, name text not null, place_id text unique, phone text, website text) on commit drop;
insert into _fill_hotel values
    ('hotel_1854', 'Four Seasons Hotel Montreal', 'ChIJV6VwVO4XyUwRNN5VaQGcqbA', '+1 514 843 2500', NULL),
    ('hotel_1855', 'Four Seasons Hotel Toronto', 'ChIJ9RKx2KQ0K4gRT1k8DuHyJkM', '+1 416 964 0411', NULL),
    ('hotel_1856', 'Four Seasons Resort and Residences Whistler', 'ChIJS97xNlU7h1QRWfk0So-xLeo', '+1 604 935 3400', NULL),
    ('hotel_1862', 'Belvedere Hotel - Kingston', 'ChIJxcp15fyq0kwRIim-Vb9AFWk', NULL, NULL),
    ('hotel_1878', 'Merrill House', 'ChIJdf9KNa3L14kR48hutIS-Rm0', NULL, 'https://www.merrill-house.com/'),
    ('hotel_1879', 'Muir, a Luxury Collection Hotel, Halifax', 'ChIJvVQTk1ojWksR23GsQ6L0D0E', '+1 902 407 6847', NULL),
    ('hotel_1881', 'Park Hyatt Toronto', 'ChIJ195p17o0K4gRLaM6S9fMmB4', '+1 416 925 1234', NULL),
    ('hotel_1883', 'Shangri-La Hotel, Toronto', 'ChIJJTGWAdI0K4gRDUDEGIaqOTc', '+1 647 788 8888', 'http://www.shangri-la.com/toronto/shangrila/'),
    ('hotel_1884', 'The Dorian, Autograph Collection', 'ChIJg57UI5BvcVMRJTUMHBpbdlw', '+1 403 300 6630', NULL),
    ('hotel_1885', 'The Lodge at Bow Lake', 'ChIJL63Ujjx5d1MRNHT5rTmwlfc', NULL, 'http://www.lodgeatbowlake.com/'),
    ('hotel_1889', 'The Smith Hotel', 'ChIJQzT4tH6r0kwRe0NOJ0acsnE', NULL, NULL);

do $$
declare bad text;
begin
  -- identity: each code must still be the CA row of that name
  select string_agg(f.code, ', ') into bad from _fill_hotel f
   where not exists (select 1 from public.hotels x where x.hotel_code = f.code and x.name = f.name and x.country_code = 'CA');
  if bad is not null then raise exception 'hotels: code is no longer the exported CA row: %', bad; end if;
  -- Place IDs are unique per table
  select string_agg(f.code || ' -> ' || f.place_id || ' (held by ' || x.hotel_code || ')', '; ') into bad
    from _fill_hotel f join public.hotels x on x.google_place_id = f.place_id and x.hotel_code <> f.code;
  if bad is not null then raise exception 'hotels: Place ID already used by another row: %', bad; end if;
end $$;

update public.hotels x set google_place_id = f.place_id, updated_at = now()
  from _fill_hotel f where x.hotel_code = f.code and f.place_id is not null and x.google_place_id is null;
update public.hotels x set phone = f.phone, updated_at = now()
  from _fill_hotel f where x.hotel_code = f.code and f.phone is not null and x.phone is null;
update public.hotels x set website_url = f.website, updated_at = now()
  from _fill_hotel f where x.hotel_code = f.code and f.website is not null and x.website_url is null;

commit;
